private int xDepth = -1, yDepth = -1;
private TreeNode xParent, yParent;

public boolean isCousins(TreeNode root, int x, int y) {
    xDepth = yDepth = -1;
    dfs(root, 0, null, x, y);
    return xDepth == yDepth && xParent != yParent;
}

void dfs(TreeNode node, int d, TreeNode p, int x, int y) {
    if (node == null || (xDepth >= 0 && yDepth >= 0)) return;   // stop once both are found
    if (node.val == x) { xDepth = d; xParent = p; }
    if (node.val == y) { yDepth = d; yParent = p; }
    dfs(node.left, d + 1, node, x, y);
    dfs(node.right, d + 1, node, x, y);
}

