void dfs(TreeNode* node, int d, TreeNode* p, int x, int y, Found& fx, Found& fy) {
    if (node == nullptr || (fx.depth >= 0 && fy.depth >= 0)) return;   // stop once both are found
    if (node->val == x) fx = {d, p};
    if (node->val == y) fy = {d, p};
    dfs(node->left, d + 1, node, x, y, fx, fy);
    dfs(node->right, d + 1, node, x, y, fx, fy);
}

