function isCousins(root, x, y) {
  const queue = [root];
  while (queue.length > 0) {
    const size = queue.length;
    let foundX = false, foundY = false;
    for (let i = 0; i < size; i++) {
      const node = queue.shift();
      if (node.val === x) foundX = true;
      if (node.val === y) foundY = true;
      if (node.left && node.right) {         // are x and y this node's two children?
        const a = node.left.val, b = node.right.val;
        if ((a === x && b === y) || (a === y && b === x)) return false;   // siblings
      }
      if (node.left) queue.push(node.left);
      if (node.right) queue.push(node.right);
    }
    if (foundX && foundY) return true;         // same level, different parents
    if (foundX || foundY) return false;        // only one of them on this level
  }
  return false;
}

from collections import deque

def is_cousins(root, x, y):
    queue = deque([root])
    while queue:
        found_x = found_y = False
        for _ in range(len(queue)):
            node = queue.popleft()
            if node.val == x:
                found_x = True
            if node.val == y:
                found_y = True
            if node.left and node.right:    # are x and y this node's two children?
                if {node.left.val, node.right.val} == {x, y}:
                    return False            # siblings
            if node.left:
                queue.append(node.left)
            if node.right:
                queue.append(node.right)
        if found_x and found_y:
            return True                     # same level, different parents
        if found_x or found_y:
            return False                    # only one of them on this level
    return False

public boolean isCousins(TreeNode root, int x, int y) {
    Queue<TreeNode> queue = new ArrayDeque<>();
    queue.offer(root);
    while (!queue.isEmpty()) {
        boolean foundX = false, foundY = false;
        for (int size = queue.size(); size > 0; size--) {
            TreeNode node = queue.poll();
            if (node.val == x) foundX = true;
            if (node.val == y) foundY = true;
            if (node.left != null && node.right != null) {   // are x and y this node's two children?
                int a = node.left.val, b = node.right.val;
                if ((a == x && b == y) || (a == y && b == x)) return false;   // siblings
            }
            if (node.left != null) queue.offer(node.left);
            if (node.right != null) queue.offer(node.right);
        }
        if (foundX && foundY) return true;     // same level, different parents
        if (foundX || foundY) return false;    // only one of them on this level
    }
    return false;
}

